types.text:
type PreparedSubmission = {
    ok: false;
    errors: ValidationError[];
} | {
    ok: true;
    submission: StoredSubmission;
    answers: PreparedAnswers;
    versionMismatch: boolean;
    derived: {
        scores: ScoreResult[];
    };
};

interface StoredSubmission {
    formId: string;
    formVersionId: string;
    schemaVersion: number;
    answeredFormVersionId: string;
    idempotencyKey: string;
    submittedAt: string;
    answers: PreparedAnswers;
    scores: ScoreResult[];
}

interface ValidationError {
    blockId: string;
    message: string;
    path: (string | number)[];
    cause?: unknown;
}

interface ValidationScope extends ValidationOptions {
    pageId?: string;
}
